function TodoApp() {
  const [todos, setTodos] = React.useState([
    { id: 1, text: 'Learn React', done: false },
    { id: 2, text: 'Build a project', done: false }
  ]);
  const [newTodo, setNewTodo] = React.useState('');
  function toggleTodo(id) {
    setTodos(todos.map(t => t.id === id ? { ...t, done: !t.done } : t));
  }
  return (
    <div>
      <h1>Todo App</h1>
      <input value={newTodo} onChange={e => setNewTodo(e.target.value)} />
      <button onClick={() => {
        setTodos([...todos, { id: Date.now(), text: newTodo, done: false }]);
        setNewTodo('');
      }}>Add</button>
      <ul>
        {todos.map(t => (
          <li key={t.id} onClick={() => toggleTodo(t.id)}
            style={{ textDecoration: t.done ? 'line-through' : 'none', cursor: 'pointer' }}>
            {t.text}
          </li>
        ))}
      </ul>
    </div>
  );
}

ReactDOM.createRoot(document.getElementById('root')).render(<TodoApp />);

function TodoApp() {
  const [todos, setTodos] = React.useState([
    { id: 1, text: 'Learn React', done: false },
    { id: 2, text: 'Build a project', done: false }
  ]);
  const [newTodo, setNewTodo] = React.useState('');
  function toggleTodo(id) {
    setTodos(todos.map(t => t.id === id ? { ...t, done: !t.done } : t));
  }
  function deleteTodo(id) {
    setTodos(todos.filter(t => t.id !== id));
  }
  return (
    <div>
      <h1>Todo App</h1>
      <input value={newTodo} onChange={e => setNewTodo(e.target.value)} />
      <button onClick={() => {
        setTodos([...todos, { id: Date.now(), text: newTodo, done: false }]);
        setNewTodo('');
      }}>Add</button>
      <ul>
        {todos.map(t => (
          <li key={t.id} onClick={() => toggleTodo(t.id)}
            style={{ textDecoration: t.done ? 'line-through' : 'none', cursor: 'pointer' }}>
            {t.text}
            <button onClick={(e) => { e.stopPropagation(); deleteTodo(t.id); }} style={{ marginLeft: 8 }}>✕</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

ReactDOM.createRoot(document.getElementById('root')).render(<TodoApp />);

function TodoApp() {
  const [todos, setTodos] = React.useState([
    { id: 1, text: 'Learn React', done: false },
    { id: 2, text: 'Build a project', done: true }
  ]);
  const [newTodo, setNewTodo] = React.useState('');
  const [filter, setFilter] = React.useState('all');
  function toggleTodo(id) {
    setTodos(todos.map(t => t.id === id ? { ...t, done: !t.done } : t));
  }
  function deleteTodo(id) {
    setTodos(todos.filter(t => t.id !== id));
  }
  const visible = todos.filter(t => filter === 'all' ? true : filter === 'active' ? !t.done : t.done);
  return (
    <div>
      <h1>Todo App</h1>
      <div>
        <button onClick={() => setFilter('all')}>All</button>
        <button onClick={() => setFilter('active')}>Active</button>
        <button onClick={() => setFilter('completed')}>Completed</button>
      </div>
      <input value={newTodo} onChange={e => setNewTodo(e.target.value)} />
      <button onClick={() => {
        setTodos([...todos, { id: Date.now(), text: newTodo, done: false }]);
        setNewTodo('');
      }}>Add</button>
      <ul>
        {visible.map(t => (
          <li key={t.id} onClick={() => toggleTodo(t.id)}
            style={{ textDecoration: t.done ? 'line-through' : 'none', cursor: 'pointer' }}>
            {t.text}
            <button onClick={(e) => { e.stopPropagation(); deleteTodo(t.id); }} style={{ marginLeft: 8 }}>✕</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

ReactDOM.createRoot(document.getElementById('root')).render(<TodoApp />);
